import assert from "node:assert/strict";
import { test } from "node:test";
import { MAX_LENGTH, slugify } from "../src/slug.ts";

test("lowercases and joins words with one hyphen", () => {
  assert.equal(slugify("Hello World"), "hello-world");
  assert.equal(slugify("a  --  b"), "a-b");
});

test("drops hyphens at both ends", () => {
  assert.equal(slugify("  --Rust & Go!--  "), "rust-go");
});

test("cuts long titles without a trailing hyphen", () => {
  const slug = slugify("The quick brown fox jumps over the lazy dog again and again");
  assert.ok(slug.length <= MAX_LENGTH);
  assert.equal(slug, "the-quick-brown-fox-jumps-over-the-lazy");
});
